begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(22);
select has_table('public', 'playlist_items', 'ordered membership exists');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid = 'public.playlist_items'::regclass), 'membership forces RLS');
select ok(not has_table_privilege('authenticated', 'public.playlist_items', 'INSERT,UPDATE,DELETE'), 'no direct membership mutations');
insert into auth.users(id, email) values ('77777777-7777-4777-8777-777777777777', 'playlist-items@rakyzu.test');
set local role authenticated;
select set_config('request.jwt.claim.sub', '77777777-7777-4777-8777-777777777777', true);
select set_config('request.jwt.claims', '{"sub":"77777777-7777-4777-8777-777777777777","role":"authenticated"}', true);
select * from public.create_playlist('90000000-0000-4000-8000-000000000001', 'Ordered', '');
select is(jsonb_array_length(public.get_playlist_detail('90000000-0000-4000-8000-000000000001')->'items'), 0, 'empty detail');
select is(public.mutate_playlist('90000000-0000-4000-8000-000000000001', 1, 'add', 'a3000000-0000-4000-8000-000000000001') #>> '{playlist,revision}', '2', 'add increments revision');
select is(public.mutate_playlist('90000000-0000-4000-8000-000000000001', 2, 'add', 'a3000000-0000-4000-8000-000000000001') #>> '{playlist,revision}', '2', 'duplicate add is no-op');
select is(public.mutate_playlist('90000000-0000-4000-8000-000000000001', 2, 'add', 'a3000000-0000-4000-8000-000000000002') #>> '{playlist,trackCount}', '2', 'count matches membership');
select throws_ok($$select public.mutate_playlist('90000000-0000-4000-8000-000000000001', 2, 'remove', 'a3000000-0000-4000-8000-000000000001')$$, 'PT409', 'Playlist revision conflict', 'stale write rejected');
select throws_ok($$select public.mutate_playlist('90000000-0000-4000-8000-000000000001', 3, 'reorder', ordered_ids => array['a3000000-0000-4000-8000-000000000001','a3000000-0000-4000-8000-000000000001']::uuid[])$$, '22023', 'Order must be an exact permutation', 'duplicate reorder rejected');
select throws_ok($$select public.mutate_playlist('90000000-0000-4000-8000-000000000001', 3, 'reorder', ordered_ids => array['a3000000-0000-4000-8000-000000000001']::uuid[])$$, '22023', 'Order must be an exact permutation', 'partial reorder rejected');
select is(public.mutate_playlist('90000000-0000-4000-8000-000000000001', 3, 'reorder', ordered_ids => array['a3000000-0000-4000-8000-000000000002','a3000000-0000-4000-8000-000000000001']::uuid[]) #>> '{items,0,trackId}', 'a3000000-0000-4000-8000-000000000002', 'order is deterministic');
select is(public.mutate_playlist('90000000-0000-4000-8000-000000000001', 4, 'metadata', playlist_name => E'\t Updated   Mix \n', playlist_description => ' Coast ') #>> '{playlist,name}', 'Updated Mix', 'edit normalizes whitespace');
select throws_ok($$select public.mutate_playlist('90000000-0000-4000-8000-000000000001', 5, 'metadata', playlist_name => ' ', playlist_description => '')$$, '22023', 'Invalid playlist metadata', 'empty edit rejected');
select throws_ok($$select public.mutate_playlist('90000000-0000-4000-8000-000000000001', 5, 'add', 'a3000000-0000-4000-8000-000000000099')$$, '22023', 'Track unavailable', 'missing track rejected');
reset role;
update public.tracks set is_published = false where id = 'a3000000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.get_playlist_detail('90000000-0000-4000-8000-000000000001') #> '{items,1,track}', 'null'::jsonb, 'unpublished metadata hidden but membership retained');
select throws_ok($$select public.mutate_playlist('90000000-0000-4000-8000-000000000001', 5, 'add', 'a3000000-0000-4000-8000-000000000001')$$, '22023', 'Track unavailable', 'unpublished track cannot be added');
select is(public.mutate_playlist('90000000-0000-4000-8000-000000000001', 5, 'remove', 'a3000000-0000-4000-8000-000000000001') #>> '{playlist,trackCount}', '1', 'unavailable membership removable');
select set_config('request.jwt.claim.sub', '88888888-8888-4888-8888-888888888888', true);
select set_config('request.jwt.claims', '{"sub":"88888888-8888-4888-8888-888888888888","role":"authenticated"}', true);
select is((select count(*)::integer from public.playlist_items), 0, 'other user cannot read items');
select throws_ok($$select public.get_playlist_detail('90000000-0000-4000-8000-000000000001')$$, '42501', 'Playlist unavailable', 'other user cannot read detail');
select throws_ok($$select public.mutate_playlist('90000000-0000-4000-8000-000000000001', 6, 'metadata', playlist_name => 'stolen', playlist_description => '')$$, '42501', 'Playlist unavailable', 'other user cannot mutate');
reset role;
set local role anon;
select throws_ok($$select public.get_playlist_detail('90000000-0000-4000-8000-000000000001')$$, '42501', 'permission denied for function get_playlist_detail', 'anonymous detail denied');
select throws_ok($$select public.mutate_playlist('90000000-0000-4000-8000-000000000001', 6, 'remove')$$, '42501', 'permission denied for function mutate_playlist', 'anonymous mutation denied');
select * from finish();
rollback;
